import random
import string


class GemAuthenticationEnv:
    GEM_POOL = (
        "Ruby", "Sapphire", "Emerald", "Amethyst", "Topaz", "Opal",
        "Garnet", "Peridot", "Aquamarine", "Citrine", "Tourmaline",
        "Zircon", "Spinel", "Beryl", "Jade", "Onyx", "Moonstone",
        "Turquoise", "Lapis", "Pearl",
    )

    def __init__(self):
        self.n = 15
        self.max_steps = 10
        self.labels = list(string.ascii_uppercase[:self.n])
        self.rng = None
        self.gem_names = {}
        self.fake_index = None
        self.candidates = set()
        self.milestones_hit = set()
        self.milestone_thresholds = (5, 2, 1)
        self.steps = 0
        self.done = False

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        names = self.rng.sample(self.GEM_POOL, self.n)
        self.gem_names = dict(zip(self.labels, names))
        self.fake_index = self.rng.randrange(self.n)
        self.candidates = set(range(self.n))
        self.milestones_hit = set()
        self.steps = 0
        self.done = False

        roster = ", ".join(f"{lab}={self.gem_names[lab]}" for lab in self.labels)
        observation = (
            "You are appraising 15 gems, labeled A through O, laid out on a table:\n"
            f"{roster}\n"
            "Exactly one gem is a counterfeit and is HEAVIER than every genuine gem; "
            "all 14 genuine gems weigh exactly the same as each other.\n"
            "Find the counterfeit using a two-pan balance scale, in at most "
            f"{self.max_steps} actions total.\n"
            "Actions (send exactly one per turn):\n"
            "  WEIGH <labels> VS <labels>  -- e.g. 'WEIGH A,B,C VS D,E,F'. "
            "The two groups must be non-empty, the same size, and share no label. "
            "The scale reports LEFT_HEAVIER, RIGHT_HEAVIER, or BALANCED.\n"
            "  GUESS <label>  -- e.g. 'GUESS G'. Names your final answer for the "
            "counterfeit and ends the game (right or wrong).\n"
            "Track what each result rules in or out yourself -- the scale only "
            "ever reports which side (if either) tipped down."
        )
        return observation, {}

    def step(self, action):
        if self.done:
            return "The appraisal has already ended.", 0.0, True, False, {}

        self.steps += 1
        text = (action or "").strip()
        upper = text.upper()

        if upper.startswith("WEIGH"):
            reward, observation, terminated = self._handle_weigh(text)
        elif upper.startswith("GUESS"):
            reward, observation, terminated = self._handle_guess(text)
        else:
            reward, terminated = 0.0, False
            observation = (
                "Unrecognized action. Use 'WEIGH <labels> VS <labels>' or "
                "'GUESS <label>'."
            )

        truncated = False
        if not terminated and self.steps >= self.max_steps:
            truncated = True
            observation += (
                f" Out of actions ({self.max_steps} used) -- the appraisal "
                "ends unresolved."
            )

        if terminated or truncated:
            self.done = True

        return observation, reward, terminated, truncated, {"step": self.steps}

    def _parse_group(self, chunk):
        parts = [p.strip().upper() for p in chunk.split(",") if p.strip()]
        if not parts:
            return None
        if any(p not in self.labels for p in parts):
            return None
        if len(parts) != len(set(parts)):
            return None
        return parts

    def _handle_weigh(self, text):
        body = text[len("WEIGH"):].strip()
        if " VS " not in body.upper():
            return 0.0, (
                "Malformed WEIGH action. Format: 'WEIGH A,B VS C,D' with two "
                "equal-size, non-overlapping groups of labels."
            ), False

        idx = body.upper().index(" VS ")
        left_raw, right_raw = body[:idx], body[idx + 4:]
        left = self._parse_group(left_raw)
        right = self._parse_group(right_raw)

        if left is None or right is None or len(left) != len(right):
            return 0.0, (
                "Invalid weighing: both sides must be non-empty, use known "
                "labels A-O, contain no repeats, and be the same size."
            ), False

        if set(left) & set(right):
            return 0.0, "Invalid weighing: a label cannot appear on both sides.", False

        left_idx = {ord(c) - ord('A') for c in left}
        right_idx = {ord(c) - ord('A') for c in right}

        if self.fake_index in left_idx:
            outcome = "LEFT_HEAVIER"
            self.candidates = self.candidates & left_idx
        elif self.fake_index in right_idx:
            outcome = "RIGHT_HEAVIER"
            self.candidates = self.candidates & right_idx
        else:
            outcome = "BALANCED"
            self.candidates = self.candidates - (left_idx | right_idx)

        reward = 0.0
        for threshold in self.milestone_thresholds:
            if threshold not in self.milestones_hit and len(self.candidates) <= threshold:
                self.milestones_hit.add(threshold)
                reward += 0.2

        observation = f"{outcome}. ({self.steps}/{self.max_steps} actions used.)"
        return reward, observation, False

    def _handle_guess(self, text):
        body = text[len("GUESS"):].strip().upper()
        if body not in self.labels:
            return 0.0, (
                "Invalid guess: name exactly one label A-O, e.g. 'GUESS G'."
            ), False

        guessed = ord(body) - ord('A')
        if guessed == self.fake_index:
            return 0.4, (
                f"Correct -- {self.gem_names[body]} ({body}) was the "
                "counterfeit. Appraisal complete."
            ), True

        correct_label = self.labels[self.fake_index]
        return 0.0, (
            f"Incorrect. {self.gem_names[body]} ({body}) was genuine; the "
            f"counterfeit was {self.gem_names[correct_label]} ({correct_label}). "
            "Appraisal complete."
        ), True

import random


class BracketSeedingEnv:
    def __init__(self):
        self.teams = ['A', 'B', 'C', 'D']
        self.max_steps = 10

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        vals = self.rng.sample(range(10, 100), 4)
        self.strengths = dict(zip(self.teams, vals))
        self.step_count = 0
        self.done = False
        self.edges = set()
        self.milestone_max_awarded = False
        self.milestone_min_awarded = False
        obs = (
            "Seed a 4-team single-elimination bracket (2 semifinals + 1 final) "
            "to MINIMIZE the tournament's total expected number of upsets. "
            "Each team's true strength is a hidden number. An 'upset' in any "
            "game is the weaker (lower-strength) team winning that game; a "
            "team with strength s beats an opponent with strength s' with "
            "probability s/(s+s'). Teams: A, B, C, D.\n"
            "Actions (exactly one per turn):\n"
            "  COMPARE X Y   - reveals which of two teams has higher hidden strength\n"
            "  SUBMIT W X Y Z - locks in (W vs X) as semifinal 1 and (Y vs Z) as "
            "semifinal 2, then ends the episode\n"
            f"You have {self.max_steps} steps total, comparisons and submit both count."
        )
        return obs, {}

    def _closure(self):
        reach = {t: set() for t in self.teams}
        for (w, l) in self.edges:
            reach[w].add(l)
        changed = True
        while changed:
            changed = False
            for t in self.teams:
                add = set()
                for x in reach[t]:
                    for y in reach[x]:
                        if y != t and y not in reach[t]:
                            add.add(y)
                if add:
                    reach[t] |= add
                    changed = True
        return reach

    def _known_max(self, reach):
        for t in self.teams:
            if len(reach[t]) == 3:
                return t
        return None

    def _known_min(self, reach):
        for t in self.teams:
            if all(t in reach[x] for x in self.teams if x != t):
                return t
        return None

    def _expected_upsets(self, a, b, c, d):
        sa, sb, sc, sd = (self.strengths[x] for x in (a, b, c, d))
        p_a = sa / (sa + sb)
        p_b = 1 - p_a
        p_c = sc / (sc + sd)
        p_d = 1 - p_c
        upset_g1 = min(sa, sb) / (sa + sb)
        upset_g2 = min(sc, sd) / (sc + sd)
        combos = [(a, c, p_a * p_c), (a, d, p_a * p_d),
                  (b, c, p_b * p_c), (b, d, p_b * p_d)]
        upset_final = 0.0
        for f1, f2, prob in combos:
            s1, s2 = self.strengths[f1], self.strengths[f2]
            upset_final += prob * (min(s1, s2) / (s1 + s2))
        return upset_g1 + upset_g2 + upset_final

    def _ranked_partitions(self):
        a = self.teams[0]
        others = self.teams[1:]
        results = []
        for i, partner in enumerate(others):
            rest = [t for t in others if t != partner]
            w, x, y, z = a, partner, rest[0], rest[1]
            val = self._expected_upsets(w, x, y, z)
            key = frozenset([frozenset((w, x)), frozenset((y, z))])
            results.append((key, val))
        results.sort(key=lambda pair: pair[1])
        return results

    def step(self, action):
        if self.done:
            return "Episode already ended.", 0.0, True, False, {}

        self.step_count += 1
        tokens = action.strip().split()
        reward = 0.0
        terminated = False
        truncated = False
        obs = ""

        if len(tokens) == 3 and tokens[0].upper() == 'COMPARE':
            a, b = tokens[1].upper(), tokens[2].upper()
            if a not in self.teams or b not in self.teams or a == b:
                obs = "Invalid COMPARE: give two distinct team letters from A, B, C, D."
            else:
                if self.strengths[a] > self.strengths[b]:
                    winner, loser = a, b
                else:
                    winner, loser = b, a
                self.edges.add((winner, loser))
                reach = self._closure()
                parts = [f"{winner} is stronger than {loser}."]
                if not self.milestone_max_awarded:
                    mx = self._known_max(reach)
                    if mx is not None:
                        self.milestone_max_awarded = True
                        reward += 0.3
                        parts.append(f"Milestone: {mx} is now provably the strongest team (+0.3).")
                if not self.milestone_min_awarded:
                    mn = self._known_min(reach)
                    if mn is not None:
                        self.milestone_min_awarded = True
                        reward += 0.3
                        parts.append(f"Milestone: {mn} is now provably the weakest team (+0.3).")
                obs = " ".join(parts) + f" Steps used: {self.step_count}/{self.max_steps}."
        elif len(tokens) == 5 and tokens[0].upper() == 'SUBMIT':
            subs = [t.upper() for t in tokens[1:]]
            if sorted(subs) != sorted(self.teams):
                obs = "Invalid SUBMIT: list all four teams A, B, C, D exactly once, e.g. SUBMIT A D B C."
            else:
                key = frozenset([frozenset(subs[0:2]), frozenset(subs[2:4])])
                value = self._expected_upsets(subs[0], subs[1], subs[2], subs[3])
                ranked = self._ranked_partitions()
                rank_index = next(i for i, (k, v) in enumerate(ranked) if k == key)
                if rank_index == 0:
                    submit_reward, verdict = 0.4, "optimal"
                elif rank_index == 1:
                    submit_reward, verdict = 0.15, "suboptimal"
                else:
                    submit_reward, verdict = 0.0, "poor"
                reward = submit_reward
                terminated = True
                self.done = True
                obs = (f"Bracket locked: ({subs[0]} vs {subs[1]}) and ({subs[2]} vs {subs[3]}). "
                       f"This pairing is {verdict} (expected upsets {value:.3f}, "
                       f"best possible {ranked[0][1]:.3f}). Reward this step: {submit_reward:.2f}.")
        else:
            obs = "Malformed action. Use 'COMPARE X Y' or 'SUBMIT W X Y Z' with team letters A, B, C, D."

        if not terminated and self.step_count >= self.max_steps:
            truncated = True
            self.done = True
            obs += " Step limit reached without a SUBMIT; episode ends."

        return obs, reward, terminated, truncated, {}
